// DecodeError reports a request that does not match the contract.
type DecodeError struct{ Err error }

func (e *DecodeError) Error() string { return "invalid request: " + e.Err.Error() }

// StatusCode lets transports map a decode failure to a client error.
func (e *DecodeError) StatusCode() int { return 400 }
